'use strict'

/**
 * cdpc 基础能力测试台（单进程服务）
 *
 * 运行：node test/test-app.js
 *      TEST_PORT=13456 node test/test-app.js     # 端口冲突时换一个
 *
 * 覆盖：进程启停 / after 依赖顺序 / autoRemove / disable-enable /
 *       ipc 通信 / limit.maxrss 的重启与停止两条分支 /
 *       pause-resume 的整树语义 / 负载信息的自身与进程树两组字段。
 *
 * cluster、sock 通道见 test/test-cluster.js。
 */

process.chdir(__dirname)

const net = require('node:net')
const {spawnSync} = require('node:child_process')
const cdpc = require('../index')

const PORT = parseInt(process.env.TEST_PORT || '3456', 10)

/**
 * 预检失败必须与「断言失败」用不同的退出码，否则 npm test 里一个遗留的
 * 端口占用看起来跟真的回归一模一样。78 = EX_CONFIG（环境/配置问题）。
 */
const EX_CONFIG = 78

let pass = 0
let fail = 0
const failed = []

function ok(cond, title, extra = '') {
  if (cond) {
    pass += 1
    console.log(`  \x1b[32mPASS\x1b[0m ${title}`)
  } else {
    fail += 1
    failed.push(title)
    console.log(`  \x1b[31mFAIL\x1b[0m ${title}${extra ? '  <' + extra + '>' : ''}`)
  }
}

const sleep = ms => new Promise(rv => setTimeout(rv, ms))
const alive = pid => { try { process.kill(pid, 0); return true } catch (e) { return false } }

function procState(pid) {
  let r = spawnSync('bash', ['-c', `awk '{print $3}' /proc/${pid}/stat 2>/dev/null || true`],
                    {encoding: 'utf8', timeout: 5000})
  return (r.stdout || '').trim()
}

/**
 * 端口预检。
 *
 * 之前没有这一步：端口被占（最常见的来源是上一次运行被强杀后遗留的
 * app1.js —— 它带 --strong，会吞掉 SIGTERM，父进程被 SIGKILL 时就成了
 * ppid=1 的孤儿）时，整个测试台会刷上百条 EADDRINUSE 堆栈，看不出根因。
 */
function preflight() {
  return new Promise(rv => {
    let s = net.createServer()

    s.once('error', err => {
      if (err.code !== 'EADDRINUSE') return rv(`绑定 ${PORT} 失败: ${err.message}`)

      let who = spawnSync('bash', ['-c', `ss -ltnp 2>/dev/null | grep ':${PORT} ' || true`],
                          {encoding: 'utf8', timeout: 5000})
      rv(`端口 ${PORT} 已被占用：\n${(who.stdout || '').trim() || '(无法确定占用者)'}\n`
        + `如果是上次遗留的测试进程：pkill -f 'cdpc/test/app1\\.js'\n`
        + `或换端口：TEST_PORT=13456 node test/test-app.js`)
    })

    s.listen(PORT, '0.0.0.0', () => s.close(() => rv('')))
  })
}

async function main() {
  let err = await preflight()

  if (err) {
    console.error(`\x1b[31m[预检失败]\x1b[0m ${err}`)
    process.exit(EX_CONFIG)
  }

  console.log(`主进程 ${process.pid}，测试端口 ${PORT}\n`)

  const cm = new cdpc({
    loadInfoFile: '--mem',   // '--mem' 是「只在内存里维护，不落盘」的哨兵值，不是文件名
    debug: false,
    errorHandle: (e, name) => {
      // AFTER 依赖、限额触发这类告警是预期内的，统一收敛成一行
      console.log(`  \x1b[33m[warn]\x1b[0m ${name} ${e && e.message ? e.message : ''}`)
    }
  })

  let ipcGot = null

  cm.runChilds([
    /**
     * httpserver 必须排在 httpclient 之前。
     * 反过来的话 httpclient 的 after 在解析时还找不到 httpserver，
     * 会直接报 --ERR-AFTER-NOT-FOUND-- 而依赖形同虚设。
     */
    {
      name: 'httpserver',
      file: 'app1.js',
      restart: 'always',
      restartDelay: 1000,
      args: ['--strong'],
      env: {APP1_PORT: PORT},
      options: {
        stdio: ['ignore', 1, 2, 'ipc']
      },
      monitorNetData: true,
      callback: (ch, cmref, chk) => {
        ch.on('message', msg => { ipcGot = msg })
        ch.send({hello: 'from-parent', pid: ch.pid})
      }
    },

    {
      name: 'httpclient',
      file: 'hcli.js',
      restart: 'count',
      restartDelay: 500,
      restartLimit: 10,
      env: {APP1_PORT: PORT},
      options: {
        stdio: ['ignore', 'ignore', 2]
      },
      after: ['httpserver']
    },

    {
      name: 'date',
      command: 'date',
      restart: 'count',
      restartDelay: 1000,
      restartLimit: 0,
      autoRemove: true,
      options: {
        stdio: ['ignore', 'ignore', 2]
      }
    },

    /**
     * limit.maxrss 的单位是 **KB**（比较对象是 /proc 里 rss 换算出来的 rssKB）。
     * 旧版本这里写的是 60000000，那等于 60GB，永远触发不了 —— 看着在测限额，
     * 实际这个分支从没被跑到过。
     *
     * 用 APP1_PORT=0 让它随机取端口，不跟 httpserver 抢。
     * maxRestart: 2 让两条分支都能跑到：先重启 2 次，再走停止。
     */
    {
      name: 'memhog',
      file: 'app1.js',
      restart: 'always',
      restartDelay: 500,
      env: {APP1_PORT: 0, APP1_RSS_MB: 120},
      options: {
        stdio: ['ignore', 'ignore', 2]
      },
      limit: {
        maxrss: 60000,
        maxRestart: 2
      }
    },

    /**
     * 进程树负载：bash 包装两个子进程。
     * 包装脚本自身几乎不耗资源，负载全在子进程上 —— 只看自身指标会误判成空闲。
     */
    {
      name: 'tree',
      command: 'bash',
      args: ['-c',
        'node -e "let x=0;setInterval(()=>{for(let i=0;i<2e7;i++)x+=i},50)" & '
        + 'node -e "let x=0;setInterval(()=>{for(let i=0;i<2e7;i++)x+=i},50)" & wait'],
      restart: 'always',
      restartDelay: 1000,
      options: {
        stdio: ['ignore', 'ignore', 2]
      }
    },

    {
      name: '',
      command: 'uname',
      args: ['-a'],
      restart: 'count',
      restartLimit: 2,
      options: {
        stdio: ['ignore', 'ignore', 2]
      },
      disabled: true
    },

    {
      name: '',
      command: 'uname',
      args: ['-nmv'],
      restart: 'count',
      restartLimit: 2,
      options: {
        stdio: ['ignore', 'ignore', 2]
      },
      disabled: true
    }
  ])

  cm.dynamicStep = 3
  cm.setStepSlice(5)
  cm.setMaxStep(2, 105)
  cm.monitorStart()

  /**
   * memhog 的限额处置发生得很快（监控一采到就动手），而 startChild 每次拉起
   * 服务都会把 cause 清空（index.js: chk.cause = ''）。事后再读只能读到最后
   * 一次的值，中间那几次重启的证据全丢了 —— 所以必须从一开始就连续采样。
   */
  const hogSeen = {causes: new Set(), pids: new Set(), states: new Set()}
  const hogTimer = setInterval(() => {
    let c = cm.childs.memhog
    if (!c) return
    if (c.cause) hogSeen.causes.add(c.cause)
    if (c.child && c.child.pid) hogSeen.pids.add(c.child.pid)
    hogSeen.states.add(cm.stateName[c.state])
  }, 50)

  // ---------------- 启动与依赖 ----------------
  console.log('[1] 启动、依赖顺序、ipc')

  await sleep(3000)

  let hs = cm.find('httpserver')

  ok(!!hs && cm.stateName[hs.state] === 'RUNNING', 'httpserver 进入 RUNNING')
  ok(!!hs && alive(hs.child.pid), 'httpserver 进程存活')
  ok(!!ipcGot && ipcGot.pid === hs.child.pid,
     'ipc 双向可用（子进程回送了自己的 pid）', JSON.stringify(ipcGot))
  ok(!!cm.find('httpclient'),
     'httpclient 的 after 依赖解析成功（httpserver 排在它前面，不再报 AFTER-NOT-FOUND）')

  // ---------------- 负载信息：自身 与 进程树 两组 ----------------
  console.log('\n[2] 负载信息的两组字段')

  let li = hs.loadinfo

  ok(li && typeof li.cpu === 'string' && typeof li.mem === 'string',
     'cpu / mem 始终是「自身」占用', `cpu=${li && li.cpu} mem=${li && li.mem}`)
  ok(li && ['cpuTotal', 'memTotal', 'procCount', 'procs', 'procsOmitted']
        .every(k => li[k] !== undefined),
     '进程树字段齐全：cpuTotal / memTotal / procCount / procs / procsOmitted')
  ok(li && Array.isArray(li.procs), 'procs 是数组（每个进程一条明细）')
  ok(li && li.net && typeof li.net.recvBytes === 'number',
     'monitorNetData 打开后有网络计数', li && li.net ? `recv=${li.net.recvBytes}` : '无')

  let tr = cm.find('tree')

  ok(!!tr && cm.stateName[tr.state] === 'RUNNING', 'tree（bash 包装）进入 RUNNING')
  ok(!!tr && tr.loadinfo.procCount >= 3,
     '包装类服务的进程树被完整识别（bash + 2 个 node）',
     `procCount=${tr && tr.loadinfo.procCount}`)
  ok(!!tr && parseFloat(tr.loadinfo.cpuTotal) > parseFloat(tr.loadinfo.cpu),
     '整树 cpu 明显高于包装进程自身 —— 只看自身会误判成空闲',
     `self=${tr && tr.loadinfo.cpu} total=${tr && tr.loadinfo.cpuTotal}`)
  ok(!!tr && parseFloat(tr.loadinfo.memTotal) > parseFloat(tr.loadinfo.mem),
     '整树 mem 高于自身')
  ok(!!tr && tr.loadinfo.procs.length >= 3 && tr.loadinfo.procs.every(p => p.pid && p.cmd),
     'procs 明细带 pid 与完整命令行，可以定位到具体是哪个子进程在吃资源')

  // ---------------- autoRemove / disable-enable ----------------
  console.log('\n[3] autoRemove 与 disable/enable')

  ok(cm.find('date') === false || cm.find('date') === null || !cm.find('date'),
     'date 跑完即退且 autoRemove 生效，已从注册表移除')

  let unames = cm.findByCommand('uname')

  ok(unames.length === 2, 'findByCommand 找到两个 uname 服务（自动命名 uname / uname-2）',
     unames.join(','))
  ok(unames.every(n => cm.childs[n].disabled === true), 'disabled 配置生效')

  for (let n of unames) {
    cm.enable(n)
    cm.start(n)
  }

  await sleep(1500)
  ok(unames.every(n => cm.childs[n].disabled === false), 'enable 后 disabled 被清除')

  // ---------------- limit.maxrss 两条分支 ----------------
  console.log('\n[4] limit.maxrss（单位 KB）')

  let mh = cm.find('memhog')
  let waited = 0

  /**
   * 结束条件只能看「是否出现过 maxrss|stop」，不能看 state === 'EXIT'：
   * 重启过程中 state 会**短暂**落在 EXIT（stop 完成、start 还没执行），
   * 早先按 EXIT 退出循环，有约 1/3 的概率在第一次重启的空档里就跳出来，
   * 于是 stop 分支还没跑到就被判定失败。真正的终态要配合 restarting 标志
   * 或者持续观察一段时间才能确认。
   */
  const sawStop = () => Array.from(hogSeen.causes).some(c => c.indexOf('maxrss|stop|') === 0)

  while (waited < 30000 && !sawStop()) {
    await sleep(100)
    waited += 100
  }

  // 终态确认：停下来之后不应该再被拉起
  await sleep(2000)
  clearInterval(hogTimer)

  let clist = Array.from(hogSeen.causes)

  ok(hogSeen.pids.size > 1,
     `超过 maxrss 后确实换了进程（观察到 ${hogSeen.pids.size} 个 pid）`)
  ok(clist.some(c => c.indexOf('maxrss|restart|') === 0),
     'restart 分支被触发，且 cause 记录了原因', clist.join(' / '))
  ok(clist.some(c => c.indexOf('maxrss|stop|') === 0),
     `超过 maxRestart 次数后转为停止，不再无限重启（${waited}ms 内收敛）`,
     clist.join(' / '))
  ok(cm.stateName[mh.state] === 'EXIT' && mh.restarting !== true,
     '最终稳定停在 EXIT 且没有在重启中，不会继续消耗系统资源',
     `state=${cm.stateName[mh.state]} restarting=${mh.restarting}`)
  ok(!mh.child || mh.child.exitCode !== null || !alive(mh.child.pid),
     '终态下没有残留的 memhog 进程')

  cm.remove('memhog')
  await sleep(500)
  ok(!cm.find('memhog'), 'memhog 移除完毕，不再干扰后续用例')

  // ---------------- pause / resume 的整树语义 ----------------
  console.log('\n[5] pause / resume（作用于整棵进程树）')

  tr = cm.find('tree')

  let treePids = [tr.child.pid].concat(tr.loadinfo.procs.map(p => p.pid))
        .filter((v, i, a) => a.indexOf(v) === i)

  cm.pause('tree')
  await sleep(1500)

  ok(cm.stateName[tr.state] === 'PAUSE', 'cdpc 状态记录为 PAUSE')
  ok(treePids.every(p => !alive(p) || procState(p) === 'T'),
     '整棵树（含子进程）都进入 stopped —— 用户看的是一个服务整体',
     treePids.map(p => `${p}:${procState(p) || '-'}`).join(' '))

  cm.resume('tree')
  await sleep(1500)

  ok(cm.stateName[tr.state] === 'RUNNING', 'resume 后状态回到 RUNNING')
  ok(treePids.every(p => !alive(p) || procState(p) !== 'T'),
     'resume 后整棵树都回到运行态')

  // ---------------- stop / start / 强杀兜底 ----------------
  console.log('\n[6] stop 的 SIGKILL 兜底（--strong 服务会吞掉 SIGTERM）')

  let oldPid = hs.child.pid
  let t0 = Date.now()

  cm.stop('httpserver')

  let stopWait = 0
  while (stopWait < 12000 && alive(oldPid)) {
    await sleep(200)
    stopWait += 200
  }

  ok(!alive(oldPid),
     `吞掉 SIGTERM 的服务最终被 SIGKILL 收走（${Date.now() - t0}ms）`)

  cm.start('httpserver')

  let upWait = 0
  while (upWait < 15000) {
    await sleep(500)
    upWait += 500
    hs = cm.find('httpserver')
    if (hs && hs.child && hs.child.pid !== oldPid
        && cm.stateName[hs.state] === 'RUNNING') break
  }

  ok(hs && hs.child && hs.child.pid !== oldPid && cm.stateName[hs.state] === 'RUNNING',
     '重新 start 后换了新 pid 并成功重新绑定端口（没有 EADDRINUSE）',
     `old=${oldPid} new=${hs && hs.child && hs.child.pid}`)

  // ---------------- 收尾：零残留 ----------------
  console.log('\n[7] 收尾')

  let allPids = []

  for (let k in cm.childs) {
    let c = cm.childs[k]
    if (c.child && c.child.pid) allPids.push(c.child.pid)
    if (c.loadinfo && Array.isArray(c.loadinfo.procs)) {
      allPids = allPids.concat(c.loadinfo.procs.map(p => p.pid))
    }
  }

  allPids = allPids.filter((v, i, a) => v && a.indexOf(v) === i)

  for (let k in Object.assign({}, cm.childs)) cm.remove(k)

  cm.monitorStop()
  await sleep(2500)

  let left = allPids.filter(alive)

  ok(left.length === 0, 'remove 全部服务后进程零残留', `残留 ${left.join(',')}`)

  // 兜底清理，避免遗留孤儿污染下一次运行的端口
  cm.killAllChilds(process.pid, 'SIGKILL')
  await sleep(300)

  console.log(`\n${'='.repeat(52)}`)
  console.log(`通过 ${pass}，失败 ${fail}`)

  if (fail > 0) {
    console.log('失败项：')
    for (let f of failed) console.log(`  - ${f}`)
  }

  console.log('='.repeat(52))

  process.exit(fail > 0 ? 1 : 0)
}

main().catch(e => {
  console.error('测试台异常：', e)
  process.exit(2)
})
